//! EFDA's source-emitted standard-treatment-guide publication record and PDF.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::doc::{GuidelineDoc,Rights};
use crate::guidelines::fetch::Fetcher;
use crate::guidelines::html::{sel,text_of};
use crate::guidelines::registry::SourceEntry;
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use url::Url;
pub struct EthiopiaStg;
const ROOT:&str="https://www.efda.gov.et/publication/stg-health-center/";
fn record(raw:&str,base:&Url)->Result<(String,String)>{let d=Html::parse_document(raw);let title=d.select(&sel("h1.entry-title")).next().map(|e|text_of(&e)).context("EFDA publication title missing")?;let links=d.select(&sel(".download-attachments li.pdf a.attachment-link[href]")).filter_map(|a|a.value().attr("href").and_then(|h|common::link(base,h))).collect::<Vec<_>>();if links.len()!=1{bail!("EFDA source record expected one PDF download wrapper")};let u=Url::parse(&links[0])?;if u.host_str()!=Some("www.efda.gov.et"){bail!("EFDA download wrapper outside source")};Ok((title,links[0].clone()))}
fn front_version(blocks:&[crate::guidelines::doc::Block])->Option<String>{let first=blocks.iter().take(15).map(|b|b.text.as_str()).collect::<Vec<_>>().join(" ").to_lowercase();if first.contains("third edition")&&first.contains("2014"){Some("Third edition, 2014".into())}else{None}}
fn sitemap_locs(xml:&str)->Vec<String>{regex::Regex::new(r"<loc>\s*([^<\s]+)\s*</loc>").unwrap().captures_iter(xml).map(|c|c[1].replace("&amp;","&")).collect()}
async fn plan_record(src:&SourceEntry,f:&Fetcher,root:&str,robots:&serde_json::Value)->Result<PlanRow>{let page=f.get_ok(root).await?;let base=Url::parse(&page.record.final_url)?;if base.host_str()!=Some("www.efda.gov.et"){bail!("EFDA source record redirected outside source")};let (title,url)=record(&page.text(),&base)?;let mut r=PlanRow{source_id:src.id.clone(),doc_key:format!("efda-{}-unresolved",common::short_hash(root)),url,title:Some(title),rendition:Some("pdf".into()),version:None,extra:json!({"record_url":root,"record_fetch":page.record,"robots_evidence":robots})};match f.get_ok(&r.url).await{Ok(p) if p.is_pdf()&&Url::parse(&p.record.final_url).is_ok_and(|u|u.host_str()==Some("www.efda.gov.et"))=>{r.doc_key=format!("efda-{}-{}",common::short_hash(root),&p.record.sha256[..12]);r.extra["pdf_sha256"]=json!(p.record.sha256)},Ok(_)=>r.extra["discovery_error"]=json!("EFDA source download did not return a same-source PDF"),Err(e)=>r.extra["discovery_error"]=json!(format!("{e:#}"))};Ok(r)}
#[async_trait::async_trait]
impl Adapter for EthiopiaStg{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let root=src.catalog_url.as_deref().unwrap_or(ROOT);let robots=match f.get("https://www.efda.gov.et/robots.txt").await {Ok(p) if p.record.status==200=>{let signal=p.text().lines().find(|l|l.trim().to_ascii_lowercase().starts_with("content-signal:")).map(String::from);json!({"source":"https://www.efda.gov.et/robots.txt","fetch":p.record,"content_signal":signal})},_=>json!(null)};
  // the catalog record first (historic row), then every other STG record of the EFDA publication sitemap
  let mut records=vec![root.to_string()];let mut extra=vec![];
  if let Some(sm)=src.config["publication_sitemap"].as_str(){let prefix=src.config["record_path_prefix"].as_str().unwrap_or("/publication/stg-");let p=f.get_ok(sm).await?;
   for loc in sitemap_locs(&p.text()){let Ok(u)=Url::parse(&loc) else {continue};if u.host_str()==Some("www.efda.gov.et")&&u.path().starts_with(prefix)&&!records.contains(&loc)&&!extra.contains(&loc){extra.push(loc)}}}
  extra.sort();records.extend(extra);let mut rows=vec![];
  for (i,rec) in records.iter().enumerate(){if limit.is_some_and(|n|rows.len()>=n){break}match plan_record(src,f,rec,&robots).await{Ok(r)=>rows.push(r),Err(e) if i>0=>rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("efda-{}-unresolved",common::short_hash(rec)),url:rec.clone(),title:None,rendition:None,version:None,extra:json!({"record_url":rec,"discovery_error":format!("{e:#}")})}),Err(e)=>return Err(e)}}
  Ok(rows)}
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("EFDA discovery: {e}")};let record_url=row.extra["record_url"].as_str().context("EFDA record URL missing")?;let page=f.get_ok(record_url).await?;let base=Url::parse(&page.record.final_url)?;if base.host_str()!=Some("www.efda.gov.et"){bail!("EFDA record redirected outside source")};let (title,url)=record(&page.text(),&base)?;if Some(title.as_str())!=row.title.as_deref()||url!=row.url{bail!("EFDA source record changed; re-plan")};let p=f.get_ok(&row.url).await?;if !p.is_pdf()||Url::parse(&p.record.final_url)?.host_str()!=Some("www.efda.gov.et")||row.extra["pdf_sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("EFDA PDF changed or unavailable; re-plan")};let(blocks,mut warnings,_)=blocks_for(&p,None,30).await?;if blocks.is_empty(){bail!("EFDA PDF yielded no text")};let version=front_version(&blocks);warnings.push("PDF table structure, care-level criteria, medication dosages, nested alternatives, diagrams and page fidelity require original-page review; no recommendation grades inferred.".into());warnings.push("One source publication record is not an exhaustive EFDA catalog; later editions, other care levels and currentness are unresolved. The observed publisher robots content signal must be assessed independently for each intended use.".into());let rights=Rights{status:"unknown".into(),note:Some("PDF and embedded asset permissions have not been established.".into()),..Default::default()};Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:Some(format!("efda-{}",common::short_hash(record_url))),title,url:row.url.clone(),item_type:Some("standard_treatment_guideline".into()),version,status:"unknown".into(),rights,blocks,fetches:vec![page.record,p.record],warnings,search_metadata:json!({"source_record":record_url,"robots_evidence":row.extra["robots_evidence"]}),..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const HC:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/health-center.html"));const GH:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/general-hospital.html"));#[test]fn real_records_emit_distinct_download_wrappers(){let(t,h)=record(HC,&Url::parse(ROOT).unwrap()).unwrap();assert_eq!(t,"STG -Health Center");assert!(h.ends_with("download.php?id=3406"));let(t,g)=record(GH,&Url::parse("https://www.efda.gov.et/publication/stg-general-hospital/").unwrap()).unwrap();assert_eq!(t,"STG-General Hospital.");assert!(g.ends_with("download.php?id=3404"));assert_ne!(h,g);}#[tokio::test]async fn missing_real_wrapper_remains_explicit(){let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,HC.as_bytes(),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"et_efda_stg","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=EthiopiaStg.discover(&src,&f,None).await.unwrap();assert_eq!(rows.len(),1);assert!(rows[0].url.ends_with("download.php?id=3406"));assert!(rows[0].extra["discovery_error"].is_string());assert!(EthiopiaStg.extract(&src,&f,&rows[0]).await.is_err());}#[test]fn genuine_front_matter_identifies_each_edition(){for input in [include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/health-center-blocks.json")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/general-hospital-blocks.json"))]{let b:Vec<crate::guidelines::doc::Block>=serde_json::from_str(input).unwrap();assert_eq!(front_version(&b).as_deref(),Some("Third edition, 2014"));}}#[tokio::test]async fn genuine_health_center_cover_pdf_path(){let pdf=include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/health-center-cover-page-1.pdf"));let(_,url)=record(HC,&Url::parse(ROOT).unwrap()).unwrap();let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,HC.as_bytes(),"text/html");f.seed_cache_for_tests(&url,pdf,"application/pdf");let src:SourceEntry=serde_json::from_value(json!({"id":"et_efda_stg","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=EthiopiaStg.discover(&src,&f,None).await.unwrap();let d=EthiopiaStg.extract(&src,&f,&rows[0]).await.unwrap();assert_eq!(d.version.as_deref(),Some("Third edition, 2014"));assert_eq!(d.rights.status,"unknown");assert!(d.warnings.iter().any(|w|w.contains("medication dosages")));assert!(!d.blocks.is_empty());}}

#[cfg(all(test, feature = "guideline-fixtures"))]mod sitemap_records{use super::*;
 const HC:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/health-center.html"));const GH:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/general-hospital.html"));
 const SM:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/et_efda_stg/publication-sitemap.xml"));
 const SMU:&str="https://www.efda.gov.et/wp-sitemap-posts-publication-1.xml";
 #[tokio::test]async fn publication_sitemap_adds_every_stg_record_after_the_catalog_record(){
  let locs=sitemap_locs(SM);assert!(locs.len()>400);assert_eq!(locs.iter().filter(|l|l.contains("/publication/stg-")).count(),3);
  let tmp=tempfile::tempdir().unwrap();let f=Fetcher::new(tmp.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(ROOT,HC.as_bytes(),"text/html");f.seed_cache_for_tests(SMU,SM.as_bytes(),"application/xml");
  let gh="https://www.efda.gov.et/publication/stg-general-hospital/";f.seed_cache_for_tests(gh,GH.as_bytes(),"text/html");
  let src:SourceEntry=serde_json::from_value(json!({"id":"et_efda_stg","access":"public","enabled":true,"catalog_url":ROOT,"config":{"publication_sitemap":SMU,"record_path_prefix":"/publication/stg-"}})).unwrap();
  let rows=EthiopiaStg.discover(&src,&f,None).await.unwrap();assert_eq!(rows.len(),3);
  assert_eq!(rows[0].extra["record_url"],ROOT);assert!(rows[0].doc_key.starts_with(&format!("efda-{}-",common::short_hash(ROOT))));
  assert_eq!(rows[1].extra["record_url"],gh);assert!(rows[1].url.ends_with("download.php?id=3404"));assert_eq!(rows[1].title.as_deref(),Some("STG-General Hospital."));
  assert_eq!(rows[2].extra["record_url"],"https://www.efda.gov.et/publication/stg-primary-hospital/");assert!(rows[2].extra["discovery_error"].is_string()&&rows[2].doc_key.ends_with("-unresolved"));
  assert_eq!(EthiopiaStg.discover(&src,&f,Some(1)).await.unwrap().len(),1);
 }
}
